SELECT collect_task_id, collect_task_no, collect_task_flow_id, collect_task_status, collect_task_trigger_type, collect_task_begin_time, collect_task_cost, collect_task_record_count, collect_task_error FROM (
(SELECT collect_task_id, collect_task_no, collect_task_flow_id, collect_task_status, collect_task_trigger_type, collect_task_begin_time, collect_task_cost, collect_task_record_count, collect_task_error FROM collect_task WHERE collect_task_flow_id = #{flowId} ORDER BY collect_task_begin_time DESC, collect_task_id DESC LIMIT 5)
) recent ORDER BY collect_task_begin_time DESC, collect_task_id DESC

mapper.update:
UPDATE collect_task
SET collect_task_node_count = COALESCE(collect_task_node_count, 0) + #{nodeCount},
    collect_task_request_count = COALESCE(collect_task_request_count, 0) + #{requestCount},
    collect_task_record_count = COALESCE(collect_task_record_count, 0) + #{recordCount}
WHERE collect_task_id = #{taskId}
